<?php

namespace App\Policies;

use Illuminate\Auth\Access\HandlesAuthorization;
use Illuminate\Foundation\Auth\User as AuthUser;

/**
 * Filament Shield policy for User. Generated by `php artisan shield:generate`;
 * each ability maps to a "{Action}:User" permission seeded by RoleSeeder.
 * super_admin bypasses these checks (Gate::before in Shield).
 *
 * Regenerating policies with shield:generate may overwrite these docblocks.
 */
class UserPolicy
{
    use HandlesAuthorization;

    /**
     * Determine whether the admin may list User records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "ViewAny:User" permission.
     */
    public function viewAny(AuthUser $authUser): bool
    {
        return $authUser->can('ViewAny:User');
    }

    /**
     * Determine whether the admin may view one User record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "View:User" permission.
     */
    public function view(AuthUser $authUser): bool
    {
        return $authUser->can('View:User');
    }

    /**
     * Determine whether the admin may create User records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "Create:User" permission.
     */
    public function create(AuthUser $authUser): bool
    {
        return $authUser->can('Create:User');
    }

    /**
     * Determine whether the admin may edit a User record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "Update:User" permission.
     */
    public function update(AuthUser $authUser): bool
    {
        return $authUser->can('Update:User');
    }

    /**
     * Determine whether the admin may delete one User record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "Delete:User" permission.
     */
    public function delete(AuthUser $authUser): bool
    {
        return $authUser->can('Delete:User');
    }

    /**
     * Determine whether the admin may bulk delete User records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "DeleteAny:User" permission.
     */
    public function deleteAny(AuthUser $authUser): bool
    {
        return $authUser->can('DeleteAny:User');
    }

    /**
     * Determine whether the admin may restore one soft-deleted User record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "Restore:User" permission.
     */
    public function restore(AuthUser $authUser): bool
    {
        return $authUser->can('Restore:User');
    }

    /**
     * Determine whether the admin may permanently delete one User record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "ForceDelete:User" permission.
     */
    public function forceDelete(AuthUser $authUser): bool
    {
        return $authUser->can('ForceDelete:User');
    }

    /**
     * Determine whether the admin may permanently bulk delete User records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "ForceDeleteAny:User" permission.
     */
    public function forceDeleteAny(AuthUser $authUser): bool
    {
        return $authUser->can('ForceDeleteAny:User');
    }

    /**
     * Determine whether the admin may bulk restore soft-deleted User records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "RestoreAny:User" permission.
     */
    public function restoreAny(AuthUser $authUser): bool
    {
        return $authUser->can('RestoreAny:User');
    }

    /**
     * Determine whether the admin may duplicate a User record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "Replicate:User" permission.
     */
    public function replicate(AuthUser $authUser): bool
    {
        return $authUser->can('Replicate:User');
    }

    /**
     * Determine whether the admin may reorder User records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "Reorder:User" permission.
     */
    public function reorder(AuthUser $authUser): bool
    {
        return $authUser->can('Reorder:User');
    }
}
